BATCH={'key':'nshore_kqzt','label':'Salem and Marblehead, Massachusetts: first-period houses, McIntire, forts and the waterfront','added':'2026-11-19 14:57'}
PEM='Peabody Essex Museum'
NPSH=L('NPS: Salem Maritime operating hours','https://www.nps.gov/sama/planyourvisit/hours.htm')
